class Solution {
    public ListNode reverseList(ListNode head) {
        ListNode prev = null, cur = head;
        while (cur != null) {
            ListNode nxt = cur.next;        // 先记住下一个
            cur.next = prev;                // 箭头掉头
            prev = cur;                     // 两个指针都往前走
            cur = nxt;
        }
        return prev;
    }
}

